css:
.pks2-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pks2-root,.pks2-root *,.pks2-root *::before,.pks2-root *::after{box-sizing:border-box}
.pks2-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pks2-root img{display:block;border:0;max-width:none}
.pks2-root [hidden]{display:none!important}
.pks2-root .nS2_1_10197{align-content:stretch;display:flex;gap:7px;align-items:center;position:relative;flex-shrink:0}
.pks2-root .nS2_1_10198{align-content:stretch;display:flex;gap:7px;align-items:center;position:relative;flex-shrink:0}
.pks2-root .nS2_1_10199{position:relative;flex-shrink:0;width:3.885px;height:3.885px}
.pks2-root .x200095{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.pks2-root .nS2_1_10200{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:14px;font-style:normal;position:relative;flex-shrink:0;font-size:0px;color:var(--wa-text, #fff);white-space:nowrap;width:48px}
.pks2-root .x200096{font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;line-height:normal;color:var(--wa-point, #46cbff);font-size:12px}
.pks2-root .x200097{line-height:normal;font-size:12px}
.pks2-root .nS2_1_10200{height:14px}
.pks2-root .nS2_1_10200>span{vertical-align:top}
.pks2-root .nS2_1_10201{align-content:stretch;display:flex;align-items:center;position:relative;flex-shrink:0;width:185px}
.pks2-root .nS2_1_10202{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:14px;font-style:normal;position:relative;flex-shrink:0;font-size:12px;color:var(--wa-text, #fff);white-space:nowrap;width:171px}
.pks2-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.pks2-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.pks2-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.pks2-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.pks2-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.pks2-root[data-theme="light"] .nS2_1_10200{color:var(--wa-text, #10231d)}
.pks2-root[data-theme="light"] .x200096{color:var(--wa-point, #047ba9)}
.pks2-root[data-theme="light"] .nS2_1_10202{color:var(--wa-text, #10231d)}
